    # The twelve products (3 sizes x 4 colours). The prices are PLACEHOLDERS taken from the scope document's
    # estimates: the team sets the real ones in the team panel before launch.
    import uuid

    products = sa.table(
        "products",
        sa.column("id", sa.Uuid()),
        sa.column("sku", sa.String()),
        sa.column("size", sa.String()),
        sa.column("colour", sa.String()),
        sa.column("name", sa.String()),
        sa.column("price", sa.Integer()),
        sa.column("active", sa.Boolean()),
        sa.column("sort_order", sa.Integer()),
    )
    base = {"COMPACT": 800, "STANDARD": 900, "LARGE": 1000}
    premium = {"BURGUNDY", "GLACIER"}
    rows = []
    for size_index, size in enumerate(base):
        for colour_index, colour in enumerate(("BLACK", "IVORY", "BURGUNDY", "GLACIER")):
            rows.append(
                {
                    "id": uuid.uuid4(),
                    "sku": f"{size}-{colour}",
                    "size": size,
                    "colour": colour,
                    "name": f"CARTAG {size.title()}, {colour.title()}",
                    "price": base[size] + (100 if colour in premium else 0),
                    "active": True,
                    "sort_order": size_index * 10 + colour_index,
                }
            )
    op.bulk_insert(products, rows)

